def compute(vars):
    operating_cash_use_millions = vars["v1"]
    receivables_thousands = vars["v2"]
    receivables_millions = receivables_thousands / 1000

    if receivables_millions == 0:
        return None

    ratio = operating_cash_use_millions / receivables_millions
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "operating_cash_use_millions": operating_cash_use_millions,
            "receivables_millions": receivables_millions,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
